package dashboard

import (
	"encoding/json"
	"os"
	"path/filepath"
	"reflect"
	"strings"
	"testing"
	"time"
)

// liveFixture is a running build: a watcher's status that says it's
// building issue 7 of gitdek/app, the agent's copy of the repository, and
// the step directory the watcher writes to.
type liveFixture struct {
	s          *Server
	ws         string // the agent's copy of the repository
	transcript string
}

func newLiveFixture(t *testing.T) liveFixture {
	t.Helper()
	work, ws := t.TempDir(), t.TempDir()
	now := time.Now().UTC()
	status := StatusPath(work, "gitdek/app")
	if err := WriteStatus(status, Status{PID: os.Getpid(), Repo: "gitdek/app", Started: now, Heartbeat: now, Every: 30, Issue: 7, Doing: "building", Since: &now}); err != nil {
		t.Fatal(err)
	}
	for p, text := range map[string]string{
		"internal/app/app.go":      "package app\n\nfunc New() {}\n",
		"internal/app/new_test.go": "package app\n",
	} {
		full := filepath.Join(ws, filepath.FromSlash(p))
		if err := os.MkdirAll(filepath.Dir(full), 0o755); err != nil {
			t.Fatal(err)
		}
		if err := os.WriteFile(full, []byte(text), 0o644); err != nil {
			t.Fatal(err)
		}
	}
	step := filepath.Join(work, "gitdek", "app", "issues", "issue-7", "build-20260928-120000")
	if err := os.MkdirAll(step, 0o755); err != nil {
		t.Fatal(err)
	}
	runs := `{"run":1,"passed":false,"failed":["TestLiveThing"],"at":"2026-09-28T12:10:00Z"}` + "\n" + `{"run":2,"passed":true,"at":"2026-09-28T12:20:00Z"}` + "\n"
	if err := os.WriteFile(filepath.Join(step, "test-runs.jsonl"), []byte(runs), 0o644); err != nil {
		t.Fatal(err)
	}
	return liveFixture{
		s:          &Server{Work: work, Repos: []*Repo{{Name: "gitdek/app", Status: status}}},
		ws:         ws,
		transcript: filepath.Join(step, "transcript.jsonl"),
	}
}

// lines is the fixture's transcript: every kind of event Claude Code's
// stream-json writes, with code, words, thinking, a command and a path
// outside the copy in them, and a last line cut off mid-write.
func (f liveFixture) lines() []string {
	q := func(s string) string { b, _ := json.Marshal(s); return string(b) }
	app, newTest := q(filepath.Join(f.ws, "internal", "app", "app.go")), q(filepath.Join(f.ws, "internal", "app", "new_test.go"))
	return []string{
		`{"type":"system","subtype":"init","cwd":` + q(f.ws) + `,"model":"claude-SECRETMODEL","tools":["Read","Edit"],"mcp_servers":[{"name":"invariant","status":"connected"}]}`,
		`{"type":"assistant","message":{"id":"m1","model":"claude-SECRETMODEL","content":[{"type":"thinking","thinking":"SECRETTHOUGHT about the plan"}],"usage":{"output_tokens":40,"thinking_tokens":30}}}`,
		`{"type":"assistant","message":{"id":"m1","model":"claude-SECRETMODEL","content":[{"type":"tool_use","id":"t1","name":"Read","input":{"file_path":` + app + `}}],"usage":{"output_tokens":55,"thinking_tokens":30}}}`,
		`{"type":"user","message":{"content":[{"type":"tool_result","tool_use_id":"t1","content":"package app // SECRETFILEBODY"}]}}`,
		`{"type":"assistant","message":{"id":"m2","content":[{"type":"text","text":"SECRETWORDS I will search next"},{"type":"tool_use","id":"t2","name":"Grep","input":{"pattern":"SECRETPATTERN","path":` + q(f.ws) + `}}],"usage":{"output_tokens":20}}}`,
		`{"type":"user","message":{"content":[{"type":"tool_result","tool_use_id":"t2","content":"internal/app/app.go"}]}}`,
		`{"type":"assistant","message":{"id":"m3","content":[{"type":"tool_use","id":"t3","name":"Read","input":{"file_path":"/Users/SECRETOUTSIDE/.netrc"}}],"usage":{"output_tokens":10}}}`,
		`{"type":"assistant","message":{"id":"m4","content":[{"type":"tool_use","id":"t4","name":"Edit","input":{"file_path":` + app + `,"old_string":"func New() {}","new_string":"func SECRETCODE() { return }"}}],"usage":{"output_tokens":70}}}`,
		`{"type":"assistant","message":{"id":"m5","content":[{"type":"tool_use","id":"t5","name":"Write","input":{"file_path":` + newTest + `,"content":"package app // SECRETWRITTEN"}}],"usage":{"output_tokens":90}}}`,
		`{"type":"system","subtype":"compact_boundary"}`,
		`{"type":"assistant","message":{"id":"m6","content":[{"type":"tool_use","id":"t6","name":"mcp__invariant__test","input":{"command":"go test ./... SECRETCOMMAND"}}],"usage":{"output_tokens":15}}}`,
		`{"type":"user","message":{"content":[{"type":"tool_result","tool_use_id":"t6","content":"FAIL TestLiveThing SECRETOUTPUT"}]}}`,
		`{"type":"assistant","message":{"id":"m7","content":[{"type":"tool_use","id":"t7","name":"Read","input":{"file_path":` + app + `}}],"usage":{"output_tokens":5}}}`,
		`{"type":"assistant","message":{"id":"m8","content":[{"type":"tool_use","id":"t8","name":"Edit","input":{"file_path":` + newTest + `,"old_string":"package app","new_string":"package app // SECRETLATE"}}],"usage":{"output_tokens":8}}}`,
	}
}

// write writes the transcript: every line but the last whole, and the last
// cut off mid-write unless whole is set.
func (f liveFixture) write(t *testing.T, whole bool) {
	t.Helper()
	ls := f.lines()
	text := strings.Join(ls[:len(ls)-1], "\n") + "\n"
	last := ls[len(ls)-1]
	if whole {
		text += last + "\n"
	} else {
		text += last[:len(last)/2]
	}
	if err := os.WriteFile(f.transcript, []byte(text), 0o644); err != nil {
		t.Fatal(err)
	}
}

func (f liveFixture) live(t *testing.T) (*Live, Watcher, []byte) {
	t.Helper()
	snap := f.s.assemble(time.Now())
	if len(snap.Repos) != 1 {
		t.Fatalf("%d repositories in the snapshot", len(snap.Repos))
	}
	w := snap.Repos[0].Factory
	if w.Live == nil {
		t.Fatalf("the running build has no live view: %+v", w)
	}
	b, err := json.Marshal(snap)
	if err != nil {
		t.Fatal(err)
	}
	return w.Live, w, b
}

func fileByPath(l *Live, p string) *LiveFile {
	for i := range l.Files {
		if l.Files[i].Path == p {
			return &l.Files[i]
		}
	}
	return nil
}

// The live view counts the agent's turns, tokens, tool calls by kind and
// files from its transcript, and skips the line still being written.
func TestLiveCountsARunningBuild(t *testing.T) {
	f := newLiveFixture(t)
	f.write(t, false)
	grew := time.Date(2026, 9, 28, 12, 30, 0, 0, time.UTC)
	if err := os.Chtimes(f.transcript, grew, grew); err != nil {
		t.Fatal(err)
	}
	l, w, _ := f.live(t)

	if l.Turns != 7 {
		t.Errorf("turns %d, want 7", l.Turns)
	}
	if l.OutputTokens != 265 {
		t.Errorf("output tokens %d, want 265: each message's largest output_tokens, summed", l.OutputTokens)
	}
	if l.ThinkingTokens != 30 {
		t.Errorf("thinking tokens %d, want 30", l.ThinkingTokens)
	}
	if want := map[string]int{"read": 3, "search": 1, "edit": 2, "test": 1}; !reflect.DeepEqual(l.Tools, want) {
		t.Errorf("tool calls by kind %v, want %v", l.Tools, want)
	}
	if want := []string{"think", "read", "search", "read", "edit", "edit", "test", "read"}; !reflect.DeepEqual(l.Marks, want) {
		t.Errorf("marks %v, want %v", l.Marks, want)
	}
	if l.Last == nil || !l.Last.Equal(grew) {
		t.Errorf("last activity %v, want when the transcript last grew, %v", l.Last, grew)
	}

	if len(l.Files) != 2 {
		t.Fatalf("files %+v, want the two inside the copy", l.Files)
	}
	app, newTest := fileByPath(l, "internal/app/app.go"), fileByPath(l, "internal/app/new_test.go")
	if app == nil || newTest == nil {
		t.Fatalf("files %+v, want paths inside the repository", l.Files)
	}
	if app.Reads != 2 || app.Edits != 1 || app.Size != int64(len("package app\n\nfunc New() {}\n")) || !app.Lit {
		t.Errorf("app.go %+v, want 2 reads, 1 edit, its size now, and lit as the last touched", *app)
	}
	if newTest.Reads != 0 || newTest.Edits != 1 || newTest.Size != int64(len("package app\n")) || newTest.Lit {
		t.Errorf("new_test.go %+v, want 1 edit, its size now, not lit", *newTest)
	}

	if w.RunsKind != "test" || len(w.Runs) != 2 {
		t.Fatalf("checkpoints %s %+v, want the build's two test runs", w.RunsKind, w.Runs)
	}
	if w.Runs[0].Passed || !reflect.DeepEqual(w.Runs[0].Failed, []string{"TestLiveThing"}) || !w.Runs[1].Passed {
		t.Errorf("checkpoints %+v, want the first failing TestLiveThing and the second passing", w.Runs)
	}
}

// The dashboard reads only what's new in the transcript, and a line cut off
// mid-write counts once it's whole.
func TestLiveReadsOnlyWhatsNew(t *testing.T) {
	f := newLiveFixture(t)
	f.write(t, false)
	if l, _, _ := f.live(t); l.Turns != 7 {
		t.Fatalf("turns %d before the last line is whole, want 7", l.Turns)
	}
	f.write(t, true)
	l, _, _ := f.live(t)
	if l.Turns != 8 || l.OutputTokens != 273 || l.Tools["edit"] != 3 || l.Tools["read"] != 3 || len(l.Marks) != 9 {
		t.Errorf("after the last line landed: %d turns, %d output tokens, tools %v, %d marks; want 8, 273, 3 edits and 3 reads, 9 marks", l.Turns, l.OutputTokens, l.Tools, len(l.Marks))
	}
	app, newTest := fileByPath(l, "internal/app/app.go"), fileByPath(l, "internal/app/new_test.go")
	if app == nil || newTest == nil || app.Lit || !newTest.Lit || newTest.Edits != 2 || app.Reads != 2 {
		t.Errorf("files %+v, want new_test.go edited twice and lit, app.go read twice", l.Files)
	}
	if l2, _, _ := f.live(t); l2.Turns != 8 || l2.Tools["edit"] != 3 {
		t.Errorf("a read with nothing new changed the counts: %d turns, tools %v", l2.Turns, l2.Tools)
	}
}

// None of the transcript's code, words, thinking, commands, tool output,
// model or paths outside the repository reach the snapshot (D-0051, D-0052).
func TestLiveShowsNothingPrivate(t *testing.T) {
	f := newLiveFixture(t)
	f.write(t, true)
	_, _, b := f.live(t)
	out := string(b)
	for _, secret := range []string{
		"SECRETMODEL", "SECRETTHOUGHT", "SECRETFILEBODY", "SECRETWORDS", "SECRETPATTERN", "SECRETOUTSIDE", ".netrc",
		"SECRETCODE", "SECRETWRITTEN", "SECRETCOMMAND", "SECRETOUTPUT", "SECRETLATE", "func New", f.ws,
	} {
		if strings.Contains(out, secret) {
			t.Errorf("the snapshot's JSON holds %q", secret)
		}
	}
	if !strings.Contains(out, `"internal/app/app.go"`) {
		t.Errorf("the snapshot's JSON doesn't name the file the agent read inside the repository")
	}
}
